// Content for the FireTrace case study (/project/p11).
// Figures come from D:/Projects/GEO: data/firetrace.sqlite, data/validation/*.json and the dated docs.
// The scrub geometry (public/data/firetrace-scrub.json) is generated by docs/design/firetrace/tools/build_scrub.mjs.
// GEO is not public yet, so source paths are shown as text rather than links.

export interface FireTraceClockEvent {
  at: string;
  label: string;
  note: string;
  shape?: "dot" | "hollow" | "square" | "hollow-square";
  above?: boolean;
}

export interface FireTraceLane {
  key: "ir" | "wf" | "fd";
  name: string;
  source: string;
  acres: string;
  band?: { at: string; seconds: number };
  link?: { from: string; to: string };
  events: FireTraceClockEvent[];
  retrieved: string;
  list: { term: string; detail: string }[];
}

export interface FireTraceDecision {
  title: string;
  body: string;
  figure: string;
  figureNote: string;
  paths: string[];
}

